def transform(grid):
    g = np.array(grid)
    bg = 0
    rows = [y for y in range(g.shape[0]) if np.all(g[y] == bg)]
    cols = [x for x in range(g.shape[1]) if np.all(g[:, x] == bg)]

    def segs(n, seps):
        out, start = [], 0
        for s in seps + [n]:
            if s > start:
                out.append((start, s - 1))
            start = s + 1
        return out

    pans = []
    for (y0, y1) in segs(g.shape[0], rows):
        for (x0, x1) in segs(g.shape[1], cols):
            pans.append(g[y0:y1 + 1, x0:x1 + 1].copy())

    from collections import Counter
    keys = [tuple(map(tuple, p)) for p in pans]
    cnt = Counter(keys)
    odd = None
    for k, p in zip(keys, pans):
        if cnt[k] == 1:
            odd = p
            break
    if odd is None:
        odd = pans[0]
    emit(odd, "Of the four quadrants separated by the empty middle row/column, three are identical; output the odd one out.")
    return odd
